package com.bank.flink.cdc;

// The four changelog kinds Flink uses to interpret CDC events.
enum RowKind {
    INSERT,         // Debezium op = c  (or r for snapshot read)
    UPDATE_BEFORE,  // the OLD image of an updated row
    UPDATE_AFTER,   // the NEW image of an updated row
    DELETE          // Debezium op = d
}
