package com.bank.flink.cdc;

// One CDC change as Debezium would emit it: op + before + after images.
class ChangeEvent {
    private final String op;            // "r","c","u","d"
    private final AccountRow before;    // null for insert/snapshot
    private final AccountRow after;     // null for delete

    ChangeEvent(String op, AccountRow before, AccountRow after) {
        this.op = op;
        this.before = before;
        this.after = after;
    }

    String getOp() { return op; }
    AccountRow getBefore() { return before; }
    AccountRow getAfter() { return after; }
}
