package com.bank.flink.cdc;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Materialises a CDC changelog into current state, keyed by primary key,
// and keeps a running SUM(balance) to show retract-then-add on updates.
class ChangelogTable {
    private static final Logger log = Logger.getLogger(ChangelogTable.class.getName());

    private final Map<String, AccountRow> current = new LinkedHashMap<>();
    private BigDecimal runningSum = BigDecimal.ZERO;

    // Apply one Debezium-style change, translating op -> RowKind(s).
    void apply(ChangeEvent e) {
        switch (e.getOp()) {
            case "r":   // snapshot read -> treated as INSERT
            case "c":   // create -> INSERT
                emit(RowKind.INSERT, e.getAfter());
                current.put(e.getAfter().getAccountId(), e.getAfter());
                runningSum = runningSum.add(e.getAfter().getBalance());
                break;
            case "u":   // update -> UPDATE_BEFORE then UPDATE_AFTER
                emit(RowKind.UPDATE_BEFORE, e.getBefore());
                runningSum = runningSum.subtract(e.getBefore().getBalance());
                emit(RowKind.UPDATE_AFTER, e.getAfter());
                current.put(e.getAfter().getAccountId(), e.getAfter());
                runningSum = runningSum.add(e.getAfter().getBalance());
                break;
            case "d":   // delete -> DELETE
                emit(RowKind.DELETE, e.getBefore());
                current.remove(e.getBefore().getAccountId());
                runningSum = runningSum.subtract(e.getBefore().getBalance());
                break;
            default:
                log.warning(() -> "unknown op: " + e.getOp());
        }
    }

    private void emit(RowKind kind, AccountRow row) {
        log.info(() -> kind + " " + row);
    }

    Map<String, AccountRow> snapshot() { return current; }
    BigDecimal runningSum() { return runningSum; }
}
