package com.bank.flink.cdc;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CdcDemo {
    private static final Logger log = Logger.getLogger(CdcDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        ChangelogTable table = new ChangelogTable();

        // Snapshot read: Rajesh's account already exists.
        table.apply(new ChangeEvent("r", null,
                new AccountRow("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"))));
        log.info("After snapshot sum=" + table.runningSum());

        // Insert: Priya opens a current account.
        table.apply(new ChangeEvent("c", null,
                new AccountRow("CUR3001", "Priya Sharma", new BigDecimal("250000"))));
        log.info("After insert sum=" + table.runningSum());

        // Update: Rajesh transfers 50000 out; balance 1000000 -> 950000.
        table.apply(new ChangeEvent("u",
                new AccountRow("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
                new AccountRow("SAV2001", "Rajesh Kumar", new BigDecimal("950000"))));
        log.info("After update sum=" + table.runningSum());

        // Delete: Priya closes her account.
        table.apply(new ChangeEvent("d",
                new AccountRow("CUR3001", "Priya Sharma", new BigDecimal("250000")), null));
        log.info("After delete sum=" + table.runningSum());

        log.info("Final materialised table: " + table.snapshot());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
